@@ -80,9 +80,10 @@
 // Iterative marking: only objects with children need a work item; every newly
 // marked object still counts toward the owned-object admission bound.
 // If scratch allocation fails, return -1 without sweeping or resetting counters.
+// A spill during traversal may leave partial marks; the next generation retries.
 fn _guarded_kernel_gc_collect(g) {
     let heap = peek32(g); let n = peek32(g + 16); let nr = peek32(g + 24);
-    let objs = peek32(g + 20); let work = 0; let allocated_work = 0;
+    let objs = peek32(g + 20); let work = 0; let allocated_work = 0; let work_capacity = 0;
     // With no registered roots every owned object is unreachable. Reclaim under
     // the same lock without reading marks, compacting survivors or clearing old
     // marks on generation wrap. There are no surviving objects on this path.
@@ -101,14 +102,17 @@
     }
     if n > 0 and nr > 0 {
         let capacity = peek32(g + 36);
-        if n <= capacity / 2 {
-            // Borrow the last n slots, disjoint from the active [0,n) entries.
-            // The lock prevents allocation/table growth until traversal ends.
-            work = objs + (capacity - n) * 4;
+        work_capacity = capacity - n;
+        if work_capacity > n { work_capacity = n; }
+        if n <= work_capacity or nr <= work_capacity {
+            // Reserve enough for all possible root work, then use spare slots
+            // even above half occupancy. Branch traversal can spill below.
+            // The lock keeps [0,n) and this borrowed tail disjoint and stable.
+            work = objs + (capacity - work_capacity) * 4;
         } else {
             allocated_work = _guarded_heap_alloc(heap, n * 4);
             if allocated_work == 0 { return 0 - 1; }
-            work = allocated_work;
+            work = allocated_work; work_capacity = n;
         }
     }
     let i = 0;
@@ -154,7 +158,21 @@
                 if marked >= n { if allocated_work != 0 { _guarded_heap_free(heap, allocated_work); } return 0 - 1; }
                 poke32(child, generation); marked = marked + 1;
                 // Leaves are complete at marking; queue only further traversal.
-                if peek32(child + 4) != 0 { poke32(work + tail * 4, child); tail = tail + 1; }
+                if peek32(child + 4) != 0 {
+                    if tail >= work_capacity {
+                        // At most one spill: every queue entry represents a
+                        // distinct marked owner, so n slots cover the full pass.
+                        allocated_work = _guarded_heap_alloc(heap, n * 4);
+                        if allocated_work == 0 { return 0 - 1; }
+                        let copied = 0;
+                        while copied < tail {
+                            poke32(allocated_work + copied * 4, peek32(work + copied * 4));
+                            copied = copied + 1;
+                        }
