+++ rejected-default-integration/stdlib/kernel/gc.sapp
@@ -79,8 +79,10 @@
 }
 // Iterative marking: only objects with children need a work item; every newly
 // marked object still counts toward the owned-object admission bound.
-// If scratch allocation fails, return -1 without sweeping or resetting counters.
-fn _guarded_kernel_gc_collect(g) {
+// Scratch OOM admits the chain fallback; unsupported topology returns -1 without
+// sweeping or resetting counters. No retry follows an ordinary marking failure.
+// Keep fallback state out of the ordinary marking/sweep function's frame.
+fn _guarded_gc_collect_with_work(g) {
     let heap = peek32(g); let n = peek32(g + 16); let nr = peek32(g + 24);
     let objs = peek32(g + 20); let work = 0; let allocated_work = 0;
     // With no registered roots every owned object is unreachable. Reclaim under
@@ -107,7 +109,7 @@
             work = objs + (capacity - n) * 4;
         } else {
             allocated_work = _guarded_heap_alloc(heap, n * 4);
-            if allocated_work == 0 { return 0 - 1; }
+            if allocated_work == 0 { return 0 - 2; }
             work = allocated_work;
         }
     }
@@ -257,3 +259,54 @@
     _kernel_memory_leave(flags); return result;
 }
 export kernel_gc_try_collect;
+
+// Allocation-failure fallback only. Prove that every owned node is a leaf or
+// single edge before changing marks. A branch preserves the original failure.
+// The caller holds the memory lock, so topology cannot change after admission.
+fn _guarded_gc_collect_chains(g) {
+    let heap = peek32(g); let n = peek32(g + 16); let nr = peek32(g + 24);
+    let objs = peek32(g + 20);
+    let i = 0;
+    while i < n {
+        if peek32(peek32(objs + i * 4) + 4) > 1 { return 0 - 1; }
+        i = i + 1;
+    }
+    let generation = peek32(g + 44);
+    if generation >= 2147483647 {
+        i = 0;
+        while i < n { poke32(peek32(objs + i * 4), 0); i = i + 1; }
+        generation = 1;
+    } else { generation = generation + 1; }
+    poke32(g + 44, generation);
+    let roots = peek32(g + 28); let marked = 0; i = 0;
+    while i < nr {
+        let obj = peek32(roots + i * 4);
+        while obj != 0 and peek32(obj) != generation {
+            if marked >= n { return 0 - 1; }
+            poke32(obj, generation); marked = marked + 1;
+            if peek32(obj + 4) == 0 { break; }
+            obj = peek32(obj + 8);
+        }
+        i = i + 1;
+    }
+    let keep = n;
+    if marked < n {
+        keep = 0; let cursor = 0; i = 0;
+        while i < n {
+            let obj = peek32(objs + i * 4);
+            if peek32(obj) == generation { poke32(objs + keep * 4, obj); keep = keep + 1; }
+            else { cursor = _guarded_heap_free_from(heap, obj, cursor); }
+            i = i + 1;
+        }
+    }
+    poke32(g + 16, keep); poke32(g + 12, 0);
+    poke32(g + 32, peek32(g + 32) + 1); return 0;
+}
+
+fn _guarded_kernel_gc_collect(g) {
+    let result = _guarded_gc_collect_with_work(g);
+    // -2 is private to the ordinary worker: only initial scratch OOM uses it.
+    // Other failures must not be retried or confused with an allocation failure.
+    if result == 0 - 2 { return _guarded_gc_collect_chains(g); }
+    return result;
+}

